import {sceneHTML,narrativeExportHTML} from './narrative-ui.js';
import {scenarioCaption} from './scenarios.js';
import {IDS,REGIONS,LAW_NAMES,controlLabel} from './model.js';
import {exposedRegion} from './event-stack.js';
import {END_REASONS} from './game-end.js';
export const LOG_KINDS={all:'All actions',events:'India events',deploy:'Deployments',administration:'Administration',parliament:'Parliament',other:'Other'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function category(h){
 if(h.kind==='deploy')return 'deploy';
 if(['event','stack-draw','phase-start','phase-ships','phase-finish'].includes(h.actionType))return 'events';
 if(['tax','unrest','govern','envoy'].includes(h.actionType))return 'administration';
 if(['law','famine','france','dilemma','parliament-finish','deregulation'].includes(h.actionType))return 'parliament';
 return 'other';
}
export function chroniclePage(state,{turn='all',kind='all',page=0}={}){
 const entries=state.history.filter(h=>(turn==='all'||h.turn===Number(turn))&&(kind==='all'||category(h)===kind)).slice().reverse();
 const pages=Math.max(1,Math.ceil(entries.length/25)),index=Math.min(Math.max(0,page),pages-1);
 return {entries:entries.slice(index*25,index*25+25),count:entries.length,page:index,pages};
}
function recordHTML(h,state){return `<div class="history-entry"><small>TURN ${h.turn} · ${esc(h.kind.toUpperCase())}</small><p>${esc(h.title)}</p>${h.report?`<details><summary>Physical instructions</summary><p class="record-report">${esc(h.report)}</p>${(h.scenes||[]).map(s=>`<blockquote><b>${esc(s.speaker)}</b> · ${esc(s.role)}<p>${esc(s.text)}</p></blockquote>`).join('')}</details>`:''}${sceneHTML(h.narrative,{archive:true,statements:state.narrative?.statements})}</div>`;}
export function chroniclePanelHTML(state,filter={}){
 const p=chroniclePage(state,filter),turn=String(filter.turn||'all'),kind=filter.kind||'all';
 return `<p class="eyebrow">CAMPAIGN CHRONICLE</p><h3>Changes to the record</h3><p class="small-note">Browse every retained entry. Newest entries appear first. Export includes the whole chronicle, regardless of these filters.</p><div class="chronicle-filters" role="group" aria-label="Filter chronicle by turn">${['all',...Array.from({length:state.turn},(_,i)=>String(i+1))].map(t=>`<button data-log-turn="${t}" aria-pressed="${turn===t}">${t==='all'?'All turns':'Turn '+t}</button>`).join('')}</div><div class="chronicle-filters" role="group" aria-label="Filter chronicle by action">${Object.entries(LOG_KINDS).map(([k,label])=>`<button data-log-kind="${k}" aria-pressed="${kind===k}">${label}</button>`).join('')}</div><p class="small-note" role="status">${p.count?`Entries ${p.page*25+1}–${Math.min((p.page+1)*25,p.count)} of ${p.count}`:'No entries match these filters.'}</p>${p.entries.map(h=>recordHTML(h,state)).join('')}<div class="chronicle-navigation"><button id="log-previous" ${p.page===0?'disabled':''}>← Newer entries</button><span>Page ${p.page+1} of ${p.pages}</span><button id="log-next" ${p.page===p.pages-1?'disabled':''}>Older entries →</button></div><button id="export-chronicle" class="wide">Export readable chronicle</button>`;
}
export function readableChronicle(state,progress=null){
 const top=exposedRegion(state.eventStack),status=state.gameEnd?END_REASONS[state.gameEnd.reason]:'In progress';
 const rows=IDS.map(id=>{const r=state.regions[id];return `<tr><th>${esc(REGIONS[id].name)}</th><td>${esc(controlLabel(state,id))}</td><td>${r.strength}</td><td>${r.unrest}</td><td>${Object.values(r.orders).filter(v=>!v).length}/${REGIONS[id].orders.length}</td><td>${r.lootAvailable?'Available':'Claimed'}</td></tr>`;}).join('');
 const turns=[...new Set(state.history.map(h=>h.turn))].sort((a,b)=>a-b);
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(state.campaignName)} · Chronicle</title><style>body{font:16px/1.6 Georgia,serif;color:#25372f;background:#fffdf6;max-width:980px;margin:40px auto;padding:0 24px}h1,h2,h3{line-height:1.3}h2{margin-top:36px;border-bottom:1px solid #bbb;padding-bottom:8px}table{width:100%;border-collapse:collapse;font:14px/1.5 Arial,sans-serif}td,th{padding:9px;border:1px solid #ccc;text-align:left}.character-silhouette{width:40px;height:50px;fill:#596158}.narrative-line{display:flex;gap:12px}.narrative-line small{display:block}.report{white-space:pre-wrap;overflow-wrap:anywhere}.entry{border-bottom:1px solid #ddd;padding:12px 0}small{color:#626b61}blockquote{border-left:3px solid #aaa;padding-left:16px}@media print{body{margin:0;padding:0;background:white}.entry,tr{break-inside:avoid}h2,h3{break-after:avoid}}@media(max-width:600px){.table-scroll{overflow:auto}body{padding:0 14px}}</style></head><body><h1>${esc(state.campaignName)}</h1><p>${scenarioCaption(state)} · <b>${esc(status)}</b></p>${state.gameEnd?.note?`<p class="report">${esc(state.gameEnd.note)}</p>`:''}<h2>Recorded board state</h2><div class="table-scroll"><table><thead><tr><th>Region</th><th>Control</th><th>Tower</th><th>Unrest</th><th>Closed orders</th><th>Loot token</th></tr></thead><tbody>${rows}</tbody></table></div><p>China office: ${state.chinaOffice?'opened':'not opened'}. Exposed stack region: ${top?esc(REGIONS[top].name):'none'}.</p><p>Active tracked laws: ${Object.entries(LAW_NAMES).filter(([id])=>state.laws[id]).map(([,name])=>esc(name)).join(', ')||'none'}.</p>${state.eventStack?.pending||progress?'<p>An action is awaiting resolution. This report shows confirmed board changes; use the JSON backup to resume the unfinished event.</p>':''}<h2>Complete chronicle</h2>${turns.length?turns.map(turn=>`<section><h2>Turn ${turn}</h2>${state.history.filter(h=>h.turn===turn).map(h=>`<article class="entry"><h3>${esc(h.title)}</h3><small>${esc(h.kind)}${h.at&&Number.isFinite(Date.parse(h.at))?' · '+esc(h.at):''}</small>${h.report?`<p class="report">${esc(h.report)}</p>`:''}${(h.scenes||[]).map(s=>`<blockquote><b>${esc(s.speaker)}</b> · ${esc(s.role)}<p>${esc(s.text)}</p></blockquote>`).join('')}${sceneHTML(h.narrative,{archive:true,statements:state.narrative?.statements})}</article>`).join('')}</section>`).join(''):'<p>No actions have been recorded.</p>'}${narrativeExportHTML(state)}<footer><p>Unofficial John Company Second Edition companion. This readable report can be printed or saved as PDF from your browser. Use the separate JSON backup to resume play in the app.</p></footer></body></html>`;
}
